namespace ghidra.app.plugin.core.datamgr.actions;









using docking;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using docking.widgets.tree.support;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.app.plugin.core.datamgr.util;
using ghidra.app.plugin.core.datamgr.util.DataTypesCopyMoveTask;
using ghidra.framework.plugintool;
using ghidra.program.model.data;

public class PasteAction : DockingAction {
	private PluginTool tool;
	private Clipboard clipboard;
	private DataTypeManagerPlugin plugin;

	public PasteAction(DataTypeManagerPlugin plugin) : base("Paste", plugin.getName())
    {
		this.plugin = plugin;
		this.clipboard = plugin.getClipboard();
		this.tool = plugin.getTool();
		setPopupMenuData(new MenuData(new string[] { "Paste" }, "Edit"));
		setKeyBindingData(
			new KeyBindingData(
				KeyStroke.getKeyStroke(KeyEvent.VK_V, DockingUtils.CONTROL_KEY_MODIFIER_MASK),
				KeyBindingPrecedence.ActionMapLevel));
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		DataTypeTreeNode node = getSelectedDataTypeTreeNode(context);
		if (node is BuiltInArchiveNode) {
			return false;
		}
		return (node != null);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		DataTypeTreeNode node = getSelectedDataTypeTreeNode(context);
		if (node == null) {
			return false;
		}
		List<GTreeNode> transferNodeList = getNodesFromClipboard();
		return canPaste(node, transferNodeList);
	}

	private DataTypeTreeNode getSelectedDataTypeTreeNode(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return null;
		}

		GTree gTree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		if (selectionPaths == null || selectionPaths.length == 0) {
			return null;
		}

		if (selectionPaths.length > 1) {
			return null;
		}

		DataTypeTreeNode node = (DataTypeTreeNode) selectionPaths[0].getLastPathComponent();
		return node;
	}

	private bool canPaste(DataTypeTreeNode destinationNode, List<GTreeNode> transferNodeList) {
		if (transferNodeList.isEmpty()) {
			return false;
		}

		if (hasInvalidCutNodes(destinationNode, transferNodeList)) {
			return false; // cut nodes that cannot be pasted here
		}

		DataTypesProvider provider = plugin.getProvider();
		DataTypeArchiveGTree tree = provider.getGTree();
		DataTypeDragNDropHandler handler = (DataTypeDragNDropHandler) tree.getDragNDropHandler();

		if (!destinationNode.canPaste(transferNodeList)) {
			return false;
		}

		DataFlavor[] flavors = handler.getSupportedDataFlavors(transferNodeList);
		return handler.isValidDataTypeDestination(destinationNode, flavors,
			DnDConstants.ACTION_COPY);
	}

	private bool hasInvalidCutNodes(DataTypeTreeNode destinationNode, List<GTreeNode> nodeList) {
		DataTypeTreeNode node = (DataTypeTreeNode) nodeList.get(0);
		if (!node.isCut()) {
			return false; // hasn't been cut, no problem
		}

		// can't cut nodes from one archive and paste into another
		DataTypeStoreNode destinationArchiveNode = destinationNode.getArchiveNode();
		foreach (GTreeNode cutNode in nodeList) {
			DataTypeTreeNode dataTypeTreeNode = (DataTypeTreeNode) cutNode;
			DataTypeStoreNode archiveNode = dataTypeTreeNode.getArchiveNode();
			if (!Objects.equals(archiveNode, destinationArchiveNode)) {
				return true; // is invalid
			}
		}

		return false; // is valid, all nodes in the same destination archive
	}

	private List<GTreeNode> getNodesFromClipboard() {
		Transferable transferable = clipboard.getContents(this);
		if (transferable is GTreeNodeTransferable) {
			GTreeNodeTransferable gtTransferable = (GTreeNodeTransferable) transferable;
			return gtTransferable.getAllData();
		}
		return Collections.emptyList();
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		List<GTreeNode> nodeList = getNodesFromClipboard();
		if (nodeList.isEmpty()) {
			return;
		}

		GTree gTree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		CategoryNode destinationNode = getDropTargetNode(selectionPaths);
		DataTypeTreeNode dataTypeTreeNode = (DataTypeTreeNode) nodeList.get(0);
		if (dataTypeTreeNode.isCut()) { // clear cut nodes on paste operation
			clipboard.setContents(null, null);
		}

		Category destination = destinationNode.getCategory();
		ActionType actionType = getActionType(dataTypeTreeNode);
		DataTypesCopyMoveTask task =
			DataTypesCopyMoveTask.forNodes(plugin, gTree, destination, nodeList, actionType);

		tool.execute(task, 250);
	}

	private CategoryNode getDropTargetNode(TreePath[] selectionPaths) {

		// clients can drop/paste onto a category or archive
		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();
		if (node is CategoryNode) {
			return (CategoryNode) node;
		}

		return (CategoryNode) node.getParent();
	}

	private ActionType getActionType(DataTypeTreeNode pasteNode) {
		if (pasteNode.isCut()) {
			return ActionType.MOVE;
		}
		return ActionType.COPY;
	}
}
